        es: {
            "skip-link": "Saltar al contenido",
            "nav.problem": "Problema", "nav.architecture": "Arquitectura", "nav.features": "Capacidades", "nav.demo": "Demo", "nav.stack": "Stack", "nav.roadmap": "Hoja de ruta", "nav.reviews": "Reseñas", "nav.faq": "FAQ", "nav.commands": "Comandos", "nav.cta": "Acceso anticipado",
            "hero.badge": "AGENT ENGINE v0.1.0 — OPEN SOURCE", "hero.title": "Tutor IA de nueva generación: del plan a las habilidades en", "hero.title.accent": "~50 horas", "hero.subtitle": "Olvídate de los videocursos pasivos. Nereus es un grafo multiagente autónomo (LangGraph) con contexto RAG local (ChromaDB) y memoria de sesión persistente.", "hero.cta": "Obtener acceso anticipado", "hero.ghost": "Cómo funciona el grafo",
            "hero.trust1": "100% Local (Ollama)", "hero.trust2": "Apache 2.0 Open Source", "hero.trust3": "Persistencia de sesiones",
            "problem.tag": "[ EL DESAFÍO ]", "problem.title": "Por qué los métodos de aprendizaje estándar no funcionan", "problem.lead": "Los videocursos tradicionales y los chats de IA comunes fallan en el dominio profundo de disciplinas de ingeniería complejas.",
            "problem.card1.title": "Alucinaciones e inexactitudes", "problem.card1.text": "Los chatbots estándar tienden a inventar APIs y sintaxis inexistentes. Nereus usa contexto RAG genuino de ChromaDB con vinculación estricta a la documentación.",
            "problem.card2.title": "Sin memoria de sesión", "problem.card2.text": "Los diálogos regulares reinician el contexto en cada reinicio. Nereus guarda el estado del autómata de grafo en una base de datos local, permitiéndole reanudar el aprendizaje en cualquier momento.",
            "problem.card3.title": "Pasividad del visionado de vídeos", "problem.card3.text": "Las clases pasivas crean una ilusión de comprensión. Nereus mantiene un diálogo constante: Agente Examinador valida conocimientos con práctica y decide si avanzar.",
            "orchestration.tag": "[ ORQUESTACIÓN ]", "orchestration.title": "Sistema de ejecución multiagente", "orchestration.lead": "Tres agentes especializados coordinan el proceso de aprendizaje en un ciclo unificado con enrutamiento automático de estado.",
            "orchestration.step1.title": "Agente Entrenador — Generador de trayectorias", "orchestration.step1.tag": "Agente planificador", "orchestration.step1.desc": "Analiza el nivel actual del usuario, descompone el objetivo global en temas y construye un grafo de aprendizaje dinámico con rutas adaptativas.",
            "orchestration.step2.title": "Agente Tutor — Profesor RAG", "orchestration.step2.tag": "Profesor", "orchestration.step2.desc": "Extrae fragmentos de contexto verificados del almacén vectorial ChromaDB, genera lecciones paso a paso y ofrece ejercicios prácticos.",
            "orchestration.step3.title": "Agente Examinador — Validador y enrutador", "orchestration.step3.tag": "Validador de conocimientos", "orchestration.step3.desc.prefix": "Evalúa la profundidad de comprensión mediante diálogo de control. Realiza enrutamiento:", "orchestration.step3.route1": "Dominado", "orchestration.step3.route.mid": "(pasar al siguiente tema) o", "orchestration.step3.route2": "Repetir", "orchestration.step3.route.end": "(reforzar material).",
            "features.tag": "[ CAPACIDADES ]", "features.title": "Ventajas arquitectónicas de Nereus", "features.lead": "Localidad completa, contexto RAG confiable y guardado persistente del progreso.",
            "features.card1.title": "Contexto de ChromaDB (RAG)", "features.card1.text": "Los embeddings vectoriales garantizan que la IA no alucine, sino que se base estrictamente en la documentación, base de código y libros de texto cargados.",
            "features.card2.title": "100% Privacidad local", "features.card2.text": "Ejecutar a través de Docker Compose y Ollama (Llama 3.2 / Qwen 2.5) significa que sus datos, diálogos y código nunca salen de su computadora.",
            "features.card3.title": "Memoria de sesión persistente", "features.card3.text": "La memoria de sesión se guarda localmente en una base de datos. Puede pausar en cualquier momento y continuar exactamente donde lo dejó.",
            "features.card4.title": "Control interactivo", "features.card4.text": "Soporte para control manual del proceso de aprendizaje, ajustes del plan actual y retroalimentación natural del usuario.",
            "demo.tag": "[ SIMULACIÓN INTERACTIVA DE GRAFO ]", "demo.title": "Grafo dinámico de agentes en acción", "demo.lead": "Los agentes pasan paquetes de datos contextuales a través de un grafo cíclico con enrutamiento de puntuaciones Agente Examinador.", "demo.pulse": "Pulso del grafo", "demo.reset": "Reiniciar nodos", "demo.start": "Iniciar",
            "stack.tag": "[ INFRAESTRUCTURA ]", "stack.title": "Stack tecnológico", "stack.lead": "Infraestructura multiagente confiable sin dependencias en la nube.",
            "roadmap.tag": "[ HOJA DE RUTA EN VIVO DE GITHUB ]", "roadmap.title": "Hoja de ruta de desarrollo", "roadmap.lead": "Las tareas y estados se cargan directamente del repositorio", "roadmap.completed": "Tareas completadas", "roadmap.active": "Tareas activas", "roadmap.more": "Más", "roadmap.status.done": "Completado", "roadmap.status.active": "En desarrollo",
            "reviews.tag": "[ OPINIONES ]", "reviews.title": "Primeras opiniones de ingenieros",
            "reviews.card1.text": "\"Dominé LangGraph y los bordes condicionales en 3 días en lugar de 3 semanas gracias al examen interactivo de temas con el Examiner.\"", "reviews.card1.name": "Iván P.", "reviews.card1.role": "Backend / Python Developer",
            "reviews.card2.text": "\"La comprensión del contexto RAG y la vectorización se reforzó a través de la verificación por diálogo del Examiner mucho mejor que viendo videos.\"", "reviews.card2.name": "Anna S.", "reviews.card2.role": "Frontend Engineer",
            "faq.tag": "[ FAQ ]", "faq.title": "Preguntas frecuentes",
            "faq.q1": "¿Cómo funciona el sistema multiagente de Nereus?", "faq.a1": "Nereus utiliza el orquestador LangGraph para crear un autómata de grafo con estado con agentes especializados: Agente Entrenador construye un mapa de temas, Agente Tutor extrae contexto RAG de ChromaDB y Agente Examinador verifica el dominio con enrutamiento de puntuaciones.",
            "faq.q2": "¿Se admite la ejecución 100% local sin APIs de terceros?", "faq.a2": "Sí, absolutamente. El proyecto se lanza con un solo comando Docker Compose: el LLM local se ejecuta en Ollama (Llama 3.2 / Qwen 2.5), el almacenamiento vectorial en ChromaDB. Sus datos y progreso nunca salen de su computadora.",
            "faq.q3": "¿Cómo funciona la persistencia y reanudación de sesiones?", "faq.a3": "El estado del grafo se guarda en una base de datos local. Al detenerse, Nereus restaurará el tema, contexto y etapas completadas con precisión hasta el último paso de diálogo.",
            "faq.q4": "¿El proyecto es gratuito y open-source? ¿Cómo obtener acceso?", "faq.a4": "El motor central de Nereus es abierto y se distribuye bajo la licencia MIT en el repositorio oficial. Puede registrarse en el formulario a continuación para recibir anuncios de pruebas o hacer fork del código fuente en GitHub.",
            "cta.badge": "PROGRAMA DE ACCESO ANTICIPADO", "cta.title": "Sea de los primeros", "cta.text": "Detenga el aprendizaje caótico. Solicite una invitación a la beta de Nereus o únase al desarrollo open-source.", "cta.placeholder": "dev@example.com", "cta.submit": "Solicitar acceso", "cta.github": "Código fuente en GitHub",
            "footer.copy": "© 2026 Nereus Labs. Licencia Apache 2.0.", "toast.default": "¡Solicitud recibida! Le contactaremos cuando se lance la prueba.",
            "cmd.goto.problem": "Ir a: Problemas de aprendizaje", "cmd.goto.arch": "Ir a: Arquitectura del grafo", "cmd.goto.features": "Ir a: Capacidades y RAG", "cmd.goto.demo": "Ir a: Demo del grafo", "cmd.goto.stack": "Ir a: Stack tecnológico", "cmd.goto.cta": "Solicitar acceso anticipado", "cmd.sim": "Lanzar simulación de grafo de agentes", "cmd.input.placeholder": "Escriba un comando o sección..."
        },
