            "features.card4.title": "Contrôle interactif", "features.card4.text": "Prise en charge du contrôle manuel du processus d'apprentissage, des ajustements du plan actuel et des retours utilisateur naturels.",
            "demo.tag": "[ SIMULATION INTERACTIVE DE GRAPHE ]", "demo.title": "Graphe dynamique d'agents en action", "demo.lead": "Les agents transmettent des paquets de données contextuels via un graphe cyclique avec routage des scores Agent Examinateur.", "demo.pulse": "Impulsion du graphe", "demo.reset": "Réinitialiser les nœuds", "demo.start": "Démarrer",
            "stack.tag": "[ INFRASTRUCTURE ]", "stack.title": "Stack technologique", "stack.lead": "Infrastructure multi-agent fiable sans dépendances cloud.",
